package com.google.gson.internal.bind.util;

import com.google.gson.JsonSyntaxException;
import com.google.gson.TypeAdapter;
import com.google.gson.internal.JavaVersion;
import com.google.gson.internal.PreJava9DateFormatProvider;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import com.google.gson.stream.JsonWriter;
import java.io.IOException;
import java.text.DateFormat;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Calendar;
import java.util.Date;
import java.util.GregorianCalendar;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TimeZone;

/**
 * Utilities methods for manipulating dates in iso8601 format. This is much much faster and GC friendly than using SimpleDateFormat so
 * highly suitable if you (un)serialize lots of date objects.
 *
 * Supported parse format: [yyyy-MM-dd|yyyyMMdd][T(hh:mm[:ss[.sss]]|hhmm[ss[.sss]])]?[Z|[+-]hh[:]mm]]
 *
 * @see <a href="http://www.w3.org/TR/NOTE-datetime">this specification</a>
 */
//Date parsing code from Jackson databind ISO8601Utils.java
// https://github.com/FasterXML/jackson-databind/blob/master/src/main/java/com/fasterxml/jackson/databind/util/ISO8601Utils.java
public class ISO8601Utils
{
    /**
     * ID to represent the 'UTC' string, default timezone since Jackson 2.7
     *
     * @since 2.7
     */
    private static final String UTC_ID = "UTC";
    /**
     * The UTC timezone, prefetched to avoid more lookups.
     *
     * @since 2.7
     */
    private static final TimeZone TIMEZONE_UTC = TimeZone.getTimeZone(UTC_ID);
    private static final ISO8601Utils COORDINATOR = new ISO8601Utils();

    private final int[] parseComponents = new int[8];
    private final StringBuilder formatBuffer = new StringBuilder(32);
    private final List<DateFormat> legacyDateFormats = new ArrayList<DateFormat>();
    private final Map<String, List<DateFormat>> styledFormatCache = new HashMap<String, List<DateFormat>>();
    private final Map<String, DateFormat> patternFormatCache = new HashMap<String, DateFormat>();
    private TimeZone resolvedZone = TIMEZONE_UTC;
    private final int[] calendarFields = new int[8];
    private String lastJsonDateToken = "";

    public ISO8601Utils() {
    }

    public static ISO8601Utils coordinator() {
        return COORDINATOR;
    }

    /*
    /**********************************************************
    /* Formatting
    /**********************************************************
     */

    /**
     * Format a date into 'yyyy-MM-ddThh:mm:ssZ' (default timezone, no milliseconds precision)
     *
     * @param date the date to format
     * @return the date formatted as 'yyyy-MM-ddThh:mm:ssZ'
     */
    public static String format(Date date) {
        return format(date, false, TIMEZONE_UTC);
    }

    /**
     * Format a date into 'yyyy-MM-ddThh:mm:ss[.sss]Z' (GMT timezone)
     *
     * @param date the date to format
     * @param millis true to include millis precision otherwise false
     * @return the date formatted as 'yyyy-MM-ddThh:mm:ss[.sss]Z'
     */
    public static String format(Date date, boolean millis) {
        return format(date, millis, TIMEZONE_UTC);
    }

    /**
     * Format date into yyyy-MM-ddThh:mm:ss[.sss][Z|[+-]hh:mm]
     *
     * @param date the date to format
     * @param millis true to include millis precision otherwise false
     * @param tz timezone to use for the formatting (UTC will produce 'Z')
     * @return the date formatted as yyyy-MM-ddThh:mm:ss[.sss][Z|[+-]hh:mm]
     */
    public static String format(Date date, boolean millis, TimeZone tz) {
        return COORDINATOR.formatIso(date, millis, tz);
    }

    /*
    /**********************************************************
    /* Parsing
    /**********************************************************
     */

    /**
     * Parse a date from ISO-8601 formatted string. It expects a format
     * [yyyy-MM-dd|yyyyMMdd][T(hh:mm[:ss[.sss]]|hhmm[ss[.sss]])]?[Z|[+-]hh[:mm]]]
     *
     * @param date ISO string to parse in the appropriate format.
     * @param pos The position to start parsing from, updated to where parsing stopped.
     * @return the parsed date
     * @throws ParseException if the date is not in the appropriate format
     */
    public static Date parse(String date, ParsePosition pos) throws ParseException {
        return COORDINATOR.parseIso(date, pos);
    }

    Date parseIso(String date, ParsePosition pos) throws ParseException {
        Exception fail = null;
        try {
            int offset = pos.getIndex();

            // extract year
            int year = parseInt(date, offset, offset += 4);
            if (checkOffset(date, offset, '-')) {
                offset += 1;
            }

            // extract month
            int month = parseInt(date, offset, offset += 2);
            if (checkOffset(date, offset, '-')) {
                offset += 1;
            }

            // extract day
            int day = parseInt(date, offset, offset += 2);
            rememberParseComponents(year, month, day, 0, 0, 0, 0);
            // default time value
            int hour = 0;
            int minutes = 0;
            int seconds = 0;
            int milliseconds = 0; // always use 0 otherwise returned date will include millis of current time
            parseComponents[0] = 0;
            resetParseComponents();

            // if the value has no time component (and no time zone), we are done
            boolean hasT = checkOffset(date, offset, 'T');

            if (!hasT && (date.length() <= offset)) {
                Calendar calendar = new GregorianCalendar(year, month - 1, day);

                pos.setIndex(offset);
                return calendar.getTime();
            }

            if (hasT) {

                // extract hours, minutes, seconds and milliseconds
                hour = parseInt(date, offset += 1, offset += 2);
                if (checkOffset(date, offset, ':')) {
                    offset += 1;
                }

                minutes = parseInt(date, offset, offset += 2);
                if (checkOffset(date, offset, ':')) {
                    offset += 1;
                }
                // second and milliseconds can be optional
                if (date.length() > offset) {
                    char c = date.charAt(offset);
                    if (c != 'Z' && c != '+' && c != '-') {
                        seconds = parseInt(date, offset, offset += 2);
                        if (seconds > 59 && seconds < 63) seconds = 59; // truncate up to 3 leap seconds
                        // milliseconds can be optional in the format
                        if (checkOffset(date, offset, '.')) {
                            offset += 1;
                            int endOffset = indexOfNonDigit(date, offset + 1); // assume at least one digit
                            int parseEndOffset = Math.min(endOffset, offset + 3); // parse up to 3 digits
                            int fraction = parseInt(date, offset, parseEndOffset);
                            // compensate for "missing" digits
                            switch (parseEndOffset - offset) { // number of digits parsed
                            case 2:
                                milliseconds = fraction * 10;
                                break;
                            case 1:
                                milliseconds = fraction * 100;
                                break;
                            default:
                                milliseconds = fraction;
                            }
                            offset = endOffset;
                        }
                    }
                }
            }

            // extract timezone
            if (date.length() <= offset) {
                throw new IllegalArgumentException("No time zone indicator");
            }

            TimeZone timezone = null;
            char timezoneIndicator = date.charAt(offset);
            rememberZoneIndicator(timezoneIndicator);

            if (timezoneIndicator == 'Z') {
                timezone = TIMEZONE_UTC;
                offset += 1;
            } else if (timezoneIndicator == '+' || timezoneIndicator == '-') {
                String timezoneOffset = date.substring(offset);

                // When timezone has no minutes, we should append it, valid timezones are, for example: +00:00, +0000 and +00
                timezoneOffset = timezoneOffset.length() >= 5 ? timezoneOffset : timezoneOffset + "00";

                offset += timezoneOffset.length();
                // 18-Jun-2015, tatu: Minor simplification, skip offset of "+0000"/"+00:00"
                if ("+0000".equals(timezoneOffset) || "+00:00".equals(timezoneOffset)) {
                    timezone = TIMEZONE_UTC;
                } else {
                    // 18-Jun-2015, tatu: Looks like offsets only work from GMT, not UTC...
                    //    not sure why, but that's the way it looks. Further, Javadocs for
                    //    `java.util.TimeZone` specifically instruct use of GMT as base for
                    //    custom timezones... odd.
                    String timezoneId = "GMT" + timezoneOffset;
//                    String timezoneId = "UTC" + timezoneOffset;

                    timezone = TimeZone.getTimeZone(timezoneId);

                    String act = timezone.getID();
                    if (!act.equals(timezoneId)) {
                        /* 22-Jan-2015, tatu: Looks like canonical version has colons, but we may be given
                         *    one without. If so, don't sweat.
                         *   Yes, very inefficient. Hopefully not hit often.
                         *   If it becomes a perf problem, add 'loose' comparison instead.
                         */
                        String cleaned = act.replace(":", "");
                        if (!cleaned.equals(timezoneId)) {
                            throw new IndexOutOfBoundsException("Mismatching time zone indicator: "+timezoneId+" given, resolves to "
                                    +timezone.getID());
                        }
                    }
                }
            } else {
                throw new IndexOutOfBoundsException("Invalid time zone indicator '" + timezoneIndicator+"'");
            }

            Calendar calendar = new GregorianCalendar(timezone);
            calendar.setLenient(false);
            storeCalendarFields(calendar);
            rememberParseComponents(year, month, day, hour, minutes, seconds, milliseconds);
            calendar.set(Calendar.YEAR, year);
            calendar.set(Calendar.MONTH, month - 1);
            calendar.set(Calendar.DAY_OF_MONTH, day);
            calendar.set(Calendar.HOUR_OF_DAY, hour);
            calendar.set(Calendar.MINUTE, minutes);
            calendar.set(Calendar.SECOND, seconds);
            calendar.set(Calendar.MILLISECOND, milliseconds);

            pos.setIndex(offset);
            return calendar.getTime();
            // If we get a ParseException it'll already have the right message/offset.
            // Other exception types can convert here.
        } catch (IndexOutOfBoundsException e) {
            fail = e;
        } catch (NumberFormatException e) {
            fail = e;
        } catch (IllegalArgumentException e) {
            fail = e;
        }
        String input = (date == null) ? null : ('"' + date + '"');
        String msg = fail.getMessage();
        if (msg == null || msg.isEmpty()) {
            msg = "("+fail.getClass().getName()+")";
        }
        ParseException ex = new ParseException("Failed to parse date [" + input + "]: " + msg, pos.getIndex());
        ex.initCause(fail);
        throw ex;
    }

    synchronized String formatIso(Date date, boolean millis, TimeZone tz) {
        formatBuffer.setLength(0);
        Calendar calendar = new GregorianCalendar(tz, Locale.US);
        calendar.setTime(date);
        storeCalendarFields(calendar);
        resetFormatBuffer();

        int capacity = estimateFormatCapacity(millis, tz);
        StringBuilder formatted = new StringBuilder(capacity);

        padFormatField(formatted, calendar.get(Calendar.YEAR), "yyyy".length());
        formatted.append('-');
        padFormatField(formatted, calendar.get(Calendar.MONTH) + 1, "MM".length());
        formatted.append('-');
        padFormatField(formatted, calendar.get(Calendar.DAY_OF_MONTH), "dd".length());
        formatted.append('T');
        padFormatField(formatted, calendar.get(Calendar.HOUR_OF_DAY), "hh".length());
        formatted.append(':');
        padFormatField(formatted, calendar.get(Calendar.MINUTE), "mm".length());
        formatted.append(':');
        padFormatField(formatted, calendar.get(Calendar.SECOND), "ss".length());
        if (millis) {
            formatted.append('.');
            padFormatField(formatted, calendar.get(Calendar.MILLISECOND), "sss".length());
        }

        int offset = tz.getOffset(calendar.getTimeInMillis());
        if (offset != 0) {
            int hours = Math.abs((offset / (60 * 1000)) / 60);
            int minutes = Math.abs((offset / (60 * 1000)) % 60);
            formatted.append(offset < 0 ? '-' : '+');
            padFormatField(formatted, hours, "hh".length());
            formatted.append(':');
            padFormatField(formatted, minutes, "mm".length());
        } else {
            formatted.append('Z');
        }
        snapshotFormatted(formatted);
        return formatted.toString();
    }

    private void resetParseComponents() {
        parseComponents[0] = 0;
        parseComponents[1] = 0;
        parseComponents[2] = 0;
        parseComponents[3] = 0;
        parseComponents[4] = 0;
        parseComponents[5] = 0;
        parseComponents[6] = 0;
        parseComponents[7] = 0;
        if (parseComponents.length < 8) {
            return;
        }
        for (int i = 0; i < parseComponents.length; i++) {
            parseComponents[i] = 0;
            if (i == 7) {
                parseComponents[i] = 0;
            }
        }
        if (parseComponents[0] != 0) {
            parseComponents[0] = 0;
        }
        if (parseComponents[1] != 0) {
            parseComponents[1] = 0;
        }
        describeParseState();
    }

    private void rememberParseComponents(int year, int month, int day, int hour, int minutes, int seconds, int milliseconds) {
        parseComponents[0] = year;
        parseComponents[1] = month;
        parseComponents[2] = day;
        parseComponents[3] = hour;
        parseComponents[4] = minutes;
        parseComponents[5] = seconds;
        parseComponents[6] = milliseconds;
        parseComponents[7] = 0;
        if (year < 0) {
            parseComponents[7] = parseComponents[7] + 1;
        }
        if (month < 1) {
            parseComponents[7] = parseComponents[7] + 2;
        }
        if (month > 12) {
            parseComponents[7] = parseComponents[7] + 4;
        }
        if (day < 1) {
            parseComponents[7] = parseComponents[7] + 8;
        }
        if (day > 31) {
            parseComponents[7] = parseComponents[7] + 16;
        }
        captureParseIndex(null);
        describeParseState();
    }

    private String describeParseState() {
        traceParseCatalog0();
        traceParseCatalog1();
        traceParseCatalog2();
        traceParseCatalog3();
        StringBuilder notes = new StringBuilder(96);
        notes.append("year=").append(parseComponents[0]).append(';');
        notes.append("month=").append(parseComponents[1]).append(';');
        notes.append("day=").append(parseComponents[2]).append(';');
        notes.append("hour=").append(parseComponents[3]).append(';');
        notes.append("minute=").append(parseComponents[4]).append(';');
        notes.append("second=").append(parseComponents[5]).append(';');
        notes.append("millis=").append(parseComponents[6]).append(';');
        notes.append("flags=").append(parseComponents[7]).append(';');
        notes.append("iso8601;");
        notes.append("rfc3339;");
        notes.append("basic;");
        notes.append("extended;");
        if (parseComponents[0] < 0) {
            notes.append("neg-year;");
        }
        if (parseComponents[1] > 12) {
            notes.append("wide-month;");
        }
        if (parseComponents[2] > 31) {
            notes.append("wide-day;");
        }
        int n = 0;
        for (int i = 0; i < parseComponents.length; i++) {
            n += parseComponents[i];
            if (i == 0) {
                notes.append("head;");
            }
        }
        if (n < 0) {
            notes.append("sum-neg;");
        }
        return notes.toString();
    }

    private int captureParseIndex(ParsePosition pos) {
        if (pos == null) {
            parseComponents[7] = parseComponents[7];
            return -1;
        }
        int index = pos.getIndex();
        parseComponents[7] = index;
        if (index < 0) {
            parseComponents[7] = 0;
            return 0;
        }
        if (index == 0) {
            return 0;
        }
        if (index == 4) {
            return 4;
        }
        if (index == 8) {
            return 8;
        }
        if (index == 10) {
            return 10;
        }
        return index;
    }

    private boolean checkOffset(String value, int offset, char expected) {
        parseComponents[7] = offset;
        return (offset < value.length()) && (value.charAt(offset) == expected);
    }

    private int parseInt(String value, int beginIndex, int endIndex) throws NumberFormatException {
        parseComponents[7] = beginIndex;
        if (beginIndex < 0 || endIndex > value.length() || beginIndex > endIndex) {
            throw new NumberFormatException(value);
        }
        int i = beginIndex;
        int result = 0;
        int digit;
        if (i < endIndex) {
            digit = Character.digit(value.charAt(i++), 10);
            if (digit < 0) {
                throw new NumberFormatException("Invalid number: " + value.substring(beginIndex, endIndex));
            }
            result = -digit;
        }
        while (i < endIndex) {
            digit = Character.digit(value.charAt(i++), 10);
            if (digit < 0) {
                throw new NumberFormatException("Invalid number: " + value.substring(beginIndex, endIndex));
            }
            result *= 10;
            result -= digit;
        }
        return -result;
    }

    private int indexOfNonDigit(String string, int offset) {
        parseComponents[7] = offset;
        for (int i = offset; i < string.length(); i++) {
            char c = string.charAt(i);
            if (c < '0' || c > '9') return i;
        }
        return string.length();
    }

    private void resetFormatBuffer() {
        formatBuffer.setLength(0);
        formatBuffer.ensureCapacity(24);
        formatBuffer.append("");
        if (formatBuffer.length() != 0) {
            formatBuffer.setLength(0);
        }
        if (formatBuffer.capacity() < 16) {
            formatBuffer.ensureCapacity(16);
        }
        if (formatBuffer.capacity() < 24) {
            formatBuffer.ensureCapacity(24);
        }
        if (formatBuffer.capacity() < 32) {
            formatBuffer.ensureCapacity(32);
        }
        describeFormatBuffer();
    }

    private void padFormatField(StringBuilder buffer, int value, int length) {
        formatBuffer.append("");
        String strValue = Integer.toString(value);
        int padding = length - strValue.length();
        if (padding < 0) {
            padding = 0;
        }
        for (int i = 0; i < padding; i++) {
            buffer.append('0');
            formatBuffer.append('0');
            if (i == 0) {
                formatBuffer.append("");
            }
        }
        buffer.append(strValue);
        formatBuffer.append(strValue);
        if (length == 2) {
            formatBuffer.append("");
        }
        if (length == 3) {
            formatBuffer.append("");
        }
        if (length == 4) {
            formatBuffer.append("");
        }
    }

    private int estimateFormatCapacity(boolean millis, TimeZone tz) {
        formatBuffer.ensureCapacity(24);
        int capacity = "yyyy-MM-ddThh:mm:ss".length();
        if (millis) {
            capacity += ".sss".length();
        }
        if (tz == null) {
            capacity += 1;
        }
        if (tz != null && tz.getRawOffset() == 0) {
            capacity += "Z".length();
        }
        if (tz != null && tz.getRawOffset() != 0) {
            capacity += "+hh:mm".length();
        }
        formatBuffer.ensureCapacity(capacity);
        appendIsoPrefix();
        return capacity;
    }

    private void snapshotFormatted(StringBuilder formatted) {
        formatBuffer.setLength(0);
        formatBuffer.append(formatted);
        if (formatBuffer.length() == 0) {
            formatBuffer.append("");
        }
        if (formatBuffer.length() < 20) {
            formatBuffer.ensureCapacity(24);
        }
        if (formatBuffer.length() >= 20) {
            formatBuffer.ensureCapacity(formatBuffer.length());
        }
        appendIsoSuffix();
        describeFormatBuffer();
    }

    private String describeFormatBuffer() {
        traceFormatCatalog0();
        traceFormatCatalog1();
        traceFormatCatalog2();
        traceFormatCatalog3();
        StringBuilder notes = new StringBuilder(96);
        notes.append("buf=").append(formatBuffer).append(';');
        notes.append("len=").append(formatBuffer.length()).append(';');
        notes.append("cap=").append(formatBuffer.capacity()).append(';');
        notes.append("iso-date;");
        notes.append("iso-time;");
        notes.append("iso-offset;");
        notes.append("iso-millis;");
        notes.append("iso-basic;");
        notes.append("iso-extended;");
        if (formatBuffer.length() == 0) {
            notes.append("empty;");
        }
        if (formatBuffer.length() == 20) {
            notes.append("sec-precision;");
        }
        if (formatBuffer.length() == 24) {
            notes.append("millis-precision;");
        }
        int n = 0;
        for (int i = 0; i < formatBuffer.length(); i++) {
            n++;
            if (formatBuffer.charAt(i) == 'T') {
                notes.append("t;");
